  function currentTown(){try{return window.ITowns?.getCurrentTown?.()||null;}catch(_){return null;}}
  function canonicalResearchId(id){const raw=String(id||''),data=window.GameData?.researches||{};if(data[raw])return raw;const aliases={booty_bpv:['booty','booty_bpv'],take_over_old:['take_over','take_over_old']};return(aliases[raw]||[raw]).find(key=>data[key])||raw;}function researchAliases(id){const canonical=canonicalResearchId(id);const map={booty:['booty','booty_bpv'],booty_bpv:['booty','booty_bpv'],take_over:['take_over','take_over_old'],take_over_old:['take_over','take_over_old']};return map[id]||map[canonical]||[canonical];}function researched(town,id){let r;try{r=town?.getResearches?.();}catch(_){}if(!r)return false;const data=r.attributes||r.toJSON?.()||r;return researchAliases(id).some(key=>{let v;try{v=typeof r.get==='function'?r.get(key):undefined;}catch(_){}if(v==null)v=data?.[key];return v===true||v===1||v==='1';});}
  function researchIdFromNode(node){const box=node?.closest?.('.research_box');const direct=box?.dataset?.researchId||box?.dataset?.research_id||node?.dataset?.researchId||node?.dataset?.research_id;if(direct)return canonicalResearchId(String(direct));const known=window.GameData?.researches||{};return canonicalResearchId([...(node?.classList||[])].find(c=>Object.prototype.hasOwnProperty.call(known,c))||[...(node?.classList||[])].find(c=>!['research_icon','research','inactive','active','disabled','research40x40','selected','locked'].includes(c))||'');}function ids(root=document){const data=window.GameData?.researches||{};/* GRCT uses GameData.researches as the authoritative research catalogue. Do not derive the overview from the currently rendered academy DOM, because Grepolis only renders a subset there. */Object.keys(data).forEach(id=>{const canonical=canonicalResearchId(id);if(canonical&&data[canonical])state.researchIds.add(canonical);});root?.querySelectorAll?.('.research_icon.research').forEach(icon=>{const id=researchIdFromNode(icon),canonical=canonicalResearchId(id);if(canonical&&data[canonical])state.researchIds.add(canonical);});return [...new Set(state.researchIds)].filter(id=>data[id]);}
  function label(id){const key=canonicalResearchId(id);return String(window.GameData?.researches?.[key]?.name||key).replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());}function researchTooltip(id,town){const key=canonicalResearchId(id),r=window.GameData?.researches?.[key]||{},parts=[label(id)];const desc=r.description||r.description_text||r.tooltip||'';if(desc)parts.push(String(desc).replace(/<[^>]+>/g,' '));if(!researched(town,id)){const c=r.resources||r.costs||r;const wood=Number(c.wood||0),stone=Number(c.stone||0),iron=Number(c.iron||0),points=Number(r.research_points||0);parts.push(`${t('resources')}: ${wood} wood, ${stone} stone, ${iron} iron · ${points} ${t('points')}`);}return parts.join('\n');}
  function attachGrctResearchTooltip(element,id,town){try{const key=canonicalResearchId(id),research=window.GameData?.researches?.[key],factory=window.GrcRTAcademyTooltipFactory;if(research&&factory?.getResearchTooltip&&window.jQuery){const academy=Number(town?.getBuildings?.()?.getBuildingLevel?.('academy')||0),points=researchPoints(town),done=researched(town,id),queued=researchQueued(town,id);window.jQuery(element).tooltip(factory.getResearchTooltip(research,academy,points,done,queued,false,townId(town)));return true;}}catch(error){console.debug('[EgelTools Academy] GRCT tooltip fallback',error);}element.title=researchTooltip(id,town);return false;}function recruitTargets(){try{return JSON.parse(localStorage.getItem('grepo_unit_targets_scoped_v2')||'{}')||{};}catch(_){return{};}}function saveRecruitTargets(data){localStorage.setItem('grepo_unit_targets_scoped_v2',JSON.stringify(data));window.dispatchEvent(new CustomEvent('egeltools:recruit-targets-updated'));}function createAcademyGroup(){const name=prompt(t('groupName'));if(!name?.trim())return null;const d=recruitTargets();d.customGroups||={};const id='academy_'+Date.now().toString(36);d.customGroups[id]={name:name.trim(),targets:{}};saveRecruitTargets(d);return'custom:'+id;}function deleteAcademyGroup(key){if(!String(key).startsWith('custom:'))return false;const id=String(key).slice(7),d=recruitTargets();delete d.customGroups?.[id];Object.entries(d.cityTargetGroups||{}).forEach(([town,a])=>{if(a===key)d.cityTargetGroups[town]='none';});saveRecruitTargets(d);return true;}function groups(){return cached('groups',liveGroups);}function liveGroups(){const out=new Map(),r=cached('targets',recruitTargets),add=(id,name)=>{id=String(id??'').trim();name=String(name??'').trim();if(id&&id!=='-1'&&id!=='-2'&&name)out.set('grepo:'+id,name);};try{const models=window.MM?.getModels?.()||{},collections=window.MM?.getCollections?.()||{};[models.TownGroup,collections.TownGroup].filter(Boolean).forEach(bucket=>{(Array.isArray(bucket)?bucket:Object.values(bucket)).forEach(entry=>{(Array.isArray(entry?.models)?entry.models:[entry]).forEach(model=>{const a=model?.attributes||model?.toJSON?.()||model||{};add(a.id??a.group_id??a.town_group_id,a.name??a.group_name??a.title);});});});}catch(error){console.debug('[EgelTools Academy] live groups',error);}Object.entries(r.grepolisGroupNames||{}).forEach(([id,name])=>add(id,name));Object.entries(r.customGroups||{}).forEach(([id,g])=>out.set('custom:'+String(id),String(g?.name||id)));return out;}
  function townGroupIndex(){const index=new Map();try{for(const bucket of Object.values(window.MM?.getModels?.()||{}))for(const m of Object.values(bucket||{})){const a=attrs(m),town=String(a.town_id??a.townId??''),group=a.town_group_id??a.group_id??a.groupId;if(group!=null&&!index.has(town))index.set(town,'grepo:'+String(group));}}catch(_){}return index;}
